    public function definitions():array{$path=['type'=>'string','description'=>'Caminho relativo à workspace'];return array_merge([$this->fn('listar_arquivos','Lista arquivos de uma pasta autorizada.',['caminho'=>$path],['caminho']),$this->fn('ler_arquivo','Lê um arquivo de texto pequeno.',['caminho'=>$path],['caminho']),$this->fn('listar_habilidades','Lista habilidades cadastradas para o agente.'),$this->fn('criar_arquivo','Cria ou substitui arquivo; substituição exige confirmado=true.',['caminho'=>$path,'conteudo'=>['type'=>'string'],'confirmado'=>['type'=>'boolean']],['caminho','conteudo']),$this->fn('copiar_arquivo','Copia arquivo dentro da workspace; substituição exige confirmado=true.',['origem'=>$path,'destino'=>$path,'confirmado'=>['type'=>'boolean']],['origem','destino']),$this->fn('eliminar_arquivo','Exclui arquivo com backup; exige confirmado=true.',['caminho'=>$path,'confirmado'=>['type'=>'boolean']],['caminho','confirmado']),$this->fn('read_file','Alias compatível com o Bonsai para ler arquivo.',['path'=>$path],['path']),$this->fn('file_glob_search','Alias compatível com o Bonsai para pesquisar por nome.',['query'=>['type'=>'string'],'path'=>$path],['query']),$this->fn('grep_search','Alias compatível com o Bonsai para pesquisar conteúdo.',['query'=>['type'=>'string'],'path'=>$path],['query']),$this->fn('write_file','Alias seguro para criar arquivo.',['path'=>$path,'content'=>['type'=>'string'],'confirmed'=>['type'=>'boolean']],['path','content']),$this->fn('edit_file','Alias seguro para editar arquivo com confirmação.',['path'=>$path,'content'=>['type'=>'string'],'confirmed'=>['type'=>'boolean']],['path','content'])],(new PhpTools($this->config,$this->workspace))->definitions());}
